 "content": "from collections import Counter

def transform(grid):
    """Insert color 2 into single-cell horizontal gaps between equal markers."""
    out = [row[:] for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    for r, row in enumerate(grid):
        markers = [c for c, value in enumerate(row) if value != bg]
        for left, right in zip(markers, markers[1:]):
            if right == left + 2 and row[left] == row[right] and row[left + 1] == bg:
                out[r][left + 1] = 2
    return out
